<template>
  <li>
    <div class="tree-row">

      <span
        class="toggle"
        v-if="hasChildren"
        @click="open = !open"
      >
        {{ open ? "▾" : "▸" }}
      </span>

      <input
        v-if="node.type === 'topology'"
        type="checkbox"
        :checked="isChecked"
        @change="onToggle"
      />

      <span
        class="node-label"
        :class="node.type"
        @click="hasChildren && (open = !open)"
      >
        {{ node.name }}
      </span>
    </div>

    <ul v-if="hasChildren && open" class="children">
      <TreeNode
        v-for="child in node.children"
        :key="child.id"
        :node="child"
        :topologyIndex="topologyIndex"

        :selectedTopologies="selectedTopologies"
        @toggle-topology="$emit('toggle-topology', ...arguments)"
      />
    </ul>
  </li>
</template>

<script setup>
import { ref, computed, defineProps, defineEmits } from "vue"

const props = defineProps({
  node: { type: Object, required: true },

  /* 🔑 최상위 topology index */
  topologyIndex: { type: Number, default: null },

  /* 🔑 ref(Set) */
  selectedTopologies: { type: Object, required: true }
})

const emit = defineEmits(["toggle-topology"])
const open = ref(true)

const hasChildren = computed(
  () => props.node.children?.length > 0
)

/* 🔥 핵심 수정: .value.has */
const isChecked = computed(() => {
  const result =
    props.node.type === "topology" &&
    props.selectedTopologies instanceof Set &&
    props.selectedTopologies.has(props.topologyIndex)


  return result
})

const onToggle = (e) => {
  e.stopPropagation()
  emit("toggle-topology", props.topologyIndex, e.target.checked)
}
</script>

<style scoped>
.tree-row {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 4px 0;
}

.toggle {
    font-size: 18px;
    /* 또는 20px */
    font-weight: bold;
    cursor: pointer;
    user-select: none;
    line-height: 1;
}

.children {
    padding-left: 20px;
    /* 기존보다 조금 더 */
    border-left: 1px dashed #d1d5db;
    /* 구조가 보이게 */
    margin-left: 5px;
}

.node-label {
    cursor: default;
}

.node-label.element {
    font-weight: 600;
}

.node-label.property-group {
    font-weight: 600;
    color: #1f2937;
}

.node-label.property {
    font-size: 13px;
    color: #374151;
}
</style>