  const addItemToZone = (zoneId, item) => {
    const zone = dropZones.value.find((z) => z.id === zoneId)
    if (!zone || zoneId !== item.id) return

    // Proxy 제거
    const newItem = cloneDeep(item)

    newItem.label = item.label
    newItem.uniqueId = generateUUID()   // ✅ 수정
    newItem.lat = 0
    newItem.lng = 0

    zone.items.push(newItem)
  }
  // =========================================================
  // ✅ 2️⃣ saveDemandArea : 신규 / 수정 모드 완전 분리
  // =========================================================
  const saveDemandArea = (address, capacity, newHoursPerDay, uniqueId = null) => {
    const zone6 = dropZones.value.find((zone) => zone.id === 6);
    if (!zone6) return "no_zone";

    // ✅ 수정 모드
    if (uniqueId) {
      const targetItem = zone6.items.find((it) => it.uniqueId === uniqueId);
      if (!targetItem) return "not_found";

      // Proxy 제거 후 복제
      const copiedProperty = cloneDeep(targetItem.property || []);
      const values = copiedProperty?.[0]?.values || [];

      values.forEach((v) => {
        if (v.name === "주소") v.data = address;
        if (v.name.replace(/\s/g, "") === "수요용량") v.data = capacity;
        if (v.name.replace(/\s/g, "") === "일별전력사용시간")
          v.data = newHoursPerDay;
      });

      targetItem.property = copiedProperty;
      targetItem.setProperty = true;
      targetItem.modifiedAt = new Date().toISOString();

      console.log(`✏️ [${targetItem.label}] 수요지역 정보 수정 완료`);
      return "updated";
    }

    const propertyTemplate = [
      {
        name: "수요지역정보",
        depth: 1,
        values: [
          { name: "주소", data: address, unit: "-", modify: false, is_default: true, depth: 2 },
          { name: "수요용량", data: capacity, unit: "MW", modify: true, is_default: true, depth: 2 },
          { name: "일별 전력 사용시간", data: newHoursPerDay, unit: "hr/day", modify: true, is_default: true, depth: 2 },
        ],
      },
    ];

    const newItem = {
      label: "수요지역",
      id: 6,
      property: cloneDeep(propertyTemplate),
      uniqueId: generateUUID(),   // ✅ 수정
      lat: 0,
      lng: 0,
      setProperty: false
    }

    zone6.items.push(newItem);
    return "added";
  };


  const removeItemFromZone = (zoneId, uniqueId) => {
    const zone = dropZones.value.find(zone => zone.id === zoneId);

    if (zone) {
      zone.items = zone.items.filter(item => item.uniqueId !== uniqueId);
    }
  };

  const getProperty = (uniqueId) => {
    for (const group of dropZones.value) {
      const item = group.items.find(element => element.uniqueId === uniqueId);
      if (item) return item; // ✅ 첫 번째 일치하는 요소를 즉시 반환
    }
    return null; // ✅ 찾지 못했을 경우 null 반환
  };
  const generateUUID = () => {
    if (window.crypto && typeof crypto.randomUUID === "function") {
      return crypto.randomUUID()
    }

    // fallback (UUID v4 유사)
    return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
      const r = Math.random() * 16 | 0
      const v = c === "x" ? r : (r & 0x3 | 0x8)
      return v.toString(16)
    })
  }


  return { dropZones, addItemToZone, saveDemandArea, removeItemFromZone, getProperty }
